def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    total_sum = sum(a)

    if total_sum == 0:
        return "0\n"

    if n == 1:
        return "-1\n"

    # Find all divisors of total_sum
    divisors = []
    i = 2
    while i * i <= total_sum:
        if total_sum % i == 0:
            divisors.append(i)
            if i != total_sum // i:
                divisors.append(total_sum // i)
        i += 1
    divisors.append(total_sum)

    min_cost = float('inf')

    for k in divisors:
        cost = 0
        prefix_sum = 0
        for x in a:
            prefix_sum += x
            remainder = prefix_sum % k
            cost += remainder
        if cost < min_cost:
            min_cost = cost

    return str(min_cost) + "\n" if min_cost != float('inf') else "-1\n"

