sys.setrecursionlimit(5000)

def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "-1"
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = defaultdict(list)

    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        x, y, w = parts
        edges.append((x, y, w, i + 1))
        adj[x].append((y, i))
        adj[y].append((x, i))

    def can_reach(start, target, blocked):
        visited = {start}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if u == target:
                return True
            for v, idx in adj[u]:
                if idx in blocked:
                    continue
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return target in visited

    # Try removing 1 edge
    best_cost = float('inf')
    best_edges = None

    for i in range(m):
        idx = edges[i][3]
        if not can_reach(s, t, {idx}):
            cost = edges[i][2]
            if cost < best_cost:
                best_cost = cost
                best_edges = edges[i][3:]

    # Try removing 2 edges
    for i in range(m):
        for j in range(i + 1, m):
            idx1 = edges[i][3]
            idx2 = edges[j][3]
            blocked = {idx1, idx2}
            if not can_reach(s, t, blocked):
                cost = edges[i][2] + edges[j][2]
                if cost < best_cost:
                    best_cost = cost
                    best_edges = sorted([idx1, idx2])

    if best_edges is None:
        return "-1"

    return f"{best_cost}\n{len(best_edges)}\n{' '.join(map(str, best_edges))}"

