def factorize(n):
    """Factorize n into prime factors"""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors


def max_flow_bfs(num_nodes, source, sink, capacity):
    """Edmonds-Karp max flow using BFS"""
    flow = 0
    residual = [[cap for cap in row] for row in capacity]

    while True:
        parent = [-1] * num_nodes
        parent[source] = source
        queue = [source]

        while queue:
            u = queue.pop(0)
            for v in range(num_nodes):
                if parent[v] == -1 and residual[u][v] > 0:
                    parent[v] = u
                    queue.append(v)
                    if v == sink:
                        break

        if parent[sink] == -1:
            break

        path_flow = float('inf')
        curr = sink
        while curr != source:
            prev = parent[curr]
            path_flow = min(path_flow, residual[prev][curr])
            curr = prev

        path_flow = int(path_flow)
        flow += path_flow

        curr = sink
        while curr != source:
            prev = parent[curr]
            residual[prev][curr] -= path_flow
            residual[curr][prev] += path_flow
            curr = prev

    return flow


