def miller_rabin(n):
    """Deterministic Miller-Rabin primality test for n < 4759123141."""
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    # Bases for deterministic Miller-Rabin up to 4,759,123,141
    for a in [2, 7, 61]:
        if a >= n:
            break
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True


def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    for a in [2, 7, 61]:
        if a >= n:
            break
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True


def is_lucky_bob(n):
    """Check if n can be represented as a^2 + b^2 where a,b >= 1."""
    if n < 2:
        return False

    temp = n
    # Remove all factors of 2
    while temp % 2 == 0:
        temp //= 2

    d = 3
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                temp //= d
                count += 1
            # If prime factor is 4k+3 and has odd exponent, can't be sum of two squares
            if d % 4 == 3 and count % 2 == 1:
                return False
        d += 2

    if temp > 1 and temp % 4 == 3:
        return False

    return True


