            all_edges.append((u, v))

    # Find all spanning trees using Union-Find
    def find(parent, x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # Generate trees
    trees = []
    for edge_set in combinations(all_edges, n - 1):
        parent = list(range(n + 1))
        edges_count = 0
        for u, v in edge_set:
            root_u = find(parent, u)
            root_v = find(parent, v)
            if root_u != root_v:
                parent[root_u] = root_v
                edges_count += 1

        if edges_count == n - 1:
            tree_set = set(edge_set)
            trees.append(tree_set)

    # Count overlaps for each k
    result = []
    for k in range(n):
        count = 0
        for tree_set in trees:
            shared = 0
            for edge in target_edges:
                if edge in tree_set:
                    shared += 1
            if shared == k:
                count += 1
        result.append(str(count % MOD))

    return ' '.join(result)

