    n, k, l = input_str.strip().split()
    n, k, l = int(n), int(k), int(l)

    MOD = 998244353

    def power(a, b):
        result = 1
        a %= MOD
        while b > 0:
            if b % 2 == 1:
                result = (result * a) % MOD
            a = (a * a) % MOD
            b //= 2
        return result

    def inverse(a):
        return power(a, MOD - 2)

    MAX_N = 2 * n + 5
    fact = [1] * MAX_N
    inv_fact = [1] * MAX_N

    for i in range(1, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD

    inv_fact[MAX_N-1] = inverse(fact[MAX_N-1])
    for i in range(MAX_N-2, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i+1)) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD

    result = 0

    for m in range(k, n + 1):
        sign = -1 if (m - k) % 2 == 1 else 1

        c1 = nCr(n, m)
        c2 = nCr(m - 1, k - 1)

        # I_m = 2^m * m! * m! / (2m+1)!
        numerator = (power(2, m) * fact[m]) % MOD
        numerator = (numerator * fact[m]) % MOD
        denominator = fact[2 * m + 1]

        I_m = (numerator * inverse(denominator)) % MOD

        term = c1 * c2 % MOD * I_m % MOD
        if sign == -1:
            result = (result - term) % MOD
        else:
            result = (result + term) % MOD

    l_mod = l % MOD
    result = (result * l_mod) % MOD

    return str(result)

