import sys

def get_diameter(n, adj):
    """BFS to find distances from a starting node"""
    dist = [-1] * (n + 1)
    dist[1] = 0
    queue = deque([1])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    # Find the farthest node
    start_node = 1
    max_dist = 0
    for i in range(1, n + 1):
        if dist[i] > max_dist:
            max_dist = dist[i]
            start_node = i

    # Second BFS from the farthest node
    dist = [-1] * (n + 1)
    dist[start_node] = 0
    queue = deque([start_node])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    # Find maximum distance (this is the diameter)
    diameter = 0
    for i in range(1, n + 1):
        if dist[i] > diameter:
            diameter = dist[i]

    return diameter

