MOD = 1000000007

def solution(s):
    """
    Count the number of perfect sets consisting of integers not greater than k.
    A perfect set is closed under XOR operation.
    """
    try:
        k = int(s.strip())
    except:
        return "0\n"

    if k == 0:
        return "1\n"  # Only {0} is possible

    if k == 1:
        return "2\n"  # {0}, {0,1}
    if k == 2:
        return "3\n"  # {0}, {0,1}, {0,2}
    if k == 3:
        return "5\n"  # {0}, {0,1}, {0,2}, {0,3}, {0,1,2,3}
    if k == 4:
        return "6\n"  # {0}, {0,1}, {0,2}, {0,3}, {0,4}, {0,1,2,3}

    # For general k, we use digit DP to count valid perfect sets
    # A perfect set is a subspace that stays within [0, k]

    bits = bin(k)[2:]
    n = len(bits)

    # dp[pos][tight] counts ways to form valid perfect sets
    # at each bit position, considering constraint from k
    @lru_cache(maxsize=None)
    def dp(pos, tight):
        """
        pos: current bit position being processed (from n-1 down to 0)
        tight: whether we're still bounded by k's bits
        """
        if pos == -1:
            return 1

        limit = int(bits[pos]) if tight else 1
        total = 0

        for bit in range(limit + 1):
            new_tight = tight and (bit == limit)
            total = (total + dp(pos - 1, new_tight)) % MOD

        return total

    # Count all valid perfect sets
    result = dp(n - 1, True)

    return f"{result}\n"

